-- Migration 0016_saas_invoices: generated by drizzle-kit (tables, constraints, indexes), triggers,
-- grants and RLS hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #252)
-- SaaS invoices (#29 part 1). Named saas_* so they never collide with the legal-gated client-fee
-- invoice tables; this migration creates no table named invoice or invoice_line.
--   * saas_invoice and saas_invoice_line are tenant tables built with tenantTable(): NOT NULL
--     workspace_id referencing organization ON DELETE cascade, a workspace-led index and ENABLE +
--     FORCE RLS with ws_isolation (exactly tenantPolicy()). A line references its invoice through
--     the composite (invoice_id, workspace_id) FK, so it cannot point into another workspace.
--   * invoice_counter is global (GLOBAL_TABLES): one gapless series per (series, fy), allocated
--     under a row lock by #253.
--   * Issued invoices are immutable (void and reissue only). app_saas_invoice_immutable() rejects
--     any UPDATE of a non-draft invoice that changes a column other than status and pdf_blob_id, or
--     moves it back to draft; app_saas_invoice_line_immutable() rejects INSERT and UPDATE of lines
--     whose invoice is not a draft. DELETE is not blocked, so deleting a workspace still cascades.
--   * New objects only: nothing existing is altered or dropped.
CREATE TABLE "invoice_counter" (
	"series" text NOT NULL,
	"fy" text NOT NULL,
	"last_number" bigint DEFAULT 0 NOT NULL,
	CONSTRAINT "invoice_counter_pkey" PRIMARY KEY("series","fy"),
	CONSTRAINT "invoice_counter_last_number_chk" CHECK (last_number >= 0)
);
--> statement-breakpoint
CREATE TABLE "saas_invoice" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"subscription_id" uuid,
	"number" text,
	"series" text NOT NULL,
	"fy" text NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"issue_date" date,
	"period_start" date,
	"period_end" date,
	"supplier" jsonb NOT NULL,
	"recipient" jsonb NOT NULL,
	"place_of_supply_state_code" text NOT NULL,
	"sac" text DEFAULT '998314' NOT NULL,
	"taxable_paise" bigint DEFAULT 0 NOT NULL,
	"cgst_paise" bigint DEFAULT 0 NOT NULL,
	"sgst_paise" bigint DEFAULT 0 NOT NULL,
	"igst_paise" bigint DEFAULT 0 NOT NULL,
	"total_paise" bigint DEFAULT 0 NOT NULL,
	"currency" text DEFAULT 'INR' NOT NULL,
	"provider_payment_id" text,
	"pdf_blob_id" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "saas_invoice_id_workspace_uq" UNIQUE("id","workspace_id"),
	CONSTRAINT "saas_invoice_status_chk" CHECK (status in ('draft', 'issued', 'paid', 'void')),
	CONSTRAINT "saas_invoice_number_issued_chk" CHECK (status = 'draft' or (number is not null and issue_date is not null)),
	CONSTRAINT "saas_invoice_place_of_supply_chk" CHECK (place_of_supply_state_code ~ '^[0-9]{2}$'),
	CONSTRAINT "saas_invoice_amounts_chk" CHECK (taxable_paise >= 0 and cgst_paise >= 0 and sgst_paise >= 0 and igst_paise >= 0 and total_paise >= 0),
	CONSTRAINT "saas_invoice_currency_chk" CHECK (currency = 'INR')
);
--> statement-breakpoint
