CREATE FUNCTION app_saas_invoice_immutable() RETURNS trigger
  LANGUAGE plpgsql SET search_path = public, pg_temp
  AS $$
    BEGIN
      IF OLD.status <> 'draft' AND (
        NEW.status = 'draft'
        OR (to_jsonb(NEW) - 'status' - 'pdf_blob_id') IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'pdf_blob_id')
      ) THEN
        RAISE EXCEPTION '% % is %: only status and pdf_blob_id may change (void and reissue)',
          TG_TABLE_NAME, OLD.id, OLD.status
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      RETURN NEW;
    END
  $$;--> statement-breakpoint
CREATE FUNCTION app_saas_invoice_line_immutable() RETURNS trigger
  LANGUAGE plpgsql SET search_path = public, pg_temp
  AS $$
    BEGIN
      IF EXISTS (
        SELECT 1 FROM saas_invoice i
        WHERE i.status <> 'draft'
          AND (i.id = NEW.invoice_id OR (TG_OP = 'UPDATE' AND i.id = OLD.invoice_id))
      ) THEN
        RAISE EXCEPTION '% of an issued invoice cannot change (void and reissue)', TG_TABLE_NAME
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      RETURN NEW;
    END
  $$;--> statement-breakpoint
CREATE TRIGGER "saas_invoice_immutable" BEFORE UPDATE ON "saas_invoice"
  FOR EACH ROW EXECUTE FUNCTION app_saas_invoice_immutable();--> statement-breakpoint
CREATE TRIGGER "saas_invoice_line_immutable" BEFORE INSERT OR UPDATE ON "saas_invoice_line"
  FOR EACH ROW EXECUTE FUNCTION app_saas_invoice_line_immutable();--> statement-breakpoint
REVOKE ALL ON FUNCTION app_saas_invoice_immutable(), app_saas_invoice_line_immutable() FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_saas_invoice_immutable(), app_saas_invoice_line_immutable() TO causedeck_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "saas_invoice", "saas_invoice_line", "invoice_counter" TO causedeck_app;--> statement-breakpoint
